  public static func createSBM(
    _ fbb: inout FlatBufferBuilder,
    MESSAGE_IDOffset MESSAGE_ID: Offset = Offset(),
    CREATION_DATEOffset CREATION_DATE: Offset = Offset(),
    ORIGINATOROffset ORIGINATOR: Offset = Offset(),
    EVENT_TYPE: sbmEventType = .unknown,
    OBJECT_CLASS: sbmObjectClass = .unknown,
    EPOCHOffset EPOCH: Offset = Offset(),
    TIME_SYSTEMOffset TIME_SYSTEM: Offset = Offset(),
    REF_FRAMEOffset REF_FRAME: Offset = Offset(),
    OBJECT_NAMEOffset OBJECT_NAME: Offset = Offset(),
    OBJECT_IDOffset OBJECT_ID: Offset = Offset(),
    NORAD_CAT_ID: UInt32 = 0,
    IMPACTOR_OBJECT_NAMEOffset IMPACTOR_OBJECT_NAME: Offset = Offset(),
    IMPACTOR_NORAD_CAT_ID: UInt32 = 0,
    TARGET_MASS_KG: Double = 0.0,
    TARGET_L_C_M: Double = 0.0,
    IMPACTOR_MASS_KG: Double = 0.0,
    IMPACTOR_L_C_M: Double = 0.0,
    RELATIVE_VELOCITY_M_PER_S: Double = 0.0,
    CATASTROPHIC: Bool = false,
    PARENT_POSITION_X_KM: Double = 0.0,
    PARENT_POSITION_Y_KM: Double = 0.0,
    PARENT_POSITION_Z_KM: Double = 0.0,
    PARENT_VELOCITY_X_KM_PER_S: Double = 0.0,
    PARENT_VELOCITY_Y_KM_PER_S: Double = 0.0,
    PARENT_VELOCITY_Z_KM_PER_S: Double = 0.0,
    MIN_LC_M: Double = 0.0,
    SEED: UInt32 = 0,
    MODEL_NAMEOffset MODEL_NAME: Offset = Offset(),
    MODEL_VERSIONOffset MODEL_VERSION: Offset = Offset(),
    FRAGMENT_COUNT: UInt32 = 0,
    INPUT_MASS_KG: Double = 0.0,
    OUTPUT_MASS_KG: Double = 0.0,
    FRAGMENTSVectorOffset FRAGMENTS: Offset = Offset(),
    ASSUMPTIONSVectorOffset ASSUMPTIONS: Offset = Offset(),
    COMMENTOffset COMMENT: Offset = Offset()
  ) -> Offset {
    let __start = SBM.startSBM(&fbb)
    SBM.add(MESSAGE_ID: MESSAGE_ID, &fbb)
    SBM.add(CREATION_DATE: CREATION_DATE, &fbb)
    SBM.add(ORIGINATOR: ORIGINATOR, &fbb)
    SBM.add(EVENT_TYPE: EVENT_TYPE, &fbb)
    SBM.add(OBJECT_CLASS: OBJECT_CLASS, &fbb)
    SBM.add(EPOCH: EPOCH, &fbb)
    SBM.add(TIME_SYSTEM: TIME_SYSTEM, &fbb)
    SBM.add(REF_FRAME: REF_FRAME, &fbb)
    SBM.add(OBJECT_NAME: OBJECT_NAME, &fbb)
    SBM.add(OBJECT_ID: OBJECT_ID, &fbb)
    SBM.add(NORAD_CAT_ID: NORAD_CAT_ID, &fbb)
    SBM.add(IMPACTOR_OBJECT_NAME: IMPACTOR_OBJECT_NAME, &fbb)
    SBM.add(IMPACTOR_NORAD_CAT_ID: IMPACTOR_NORAD_CAT_ID, &fbb)
    SBM.add(TARGET_MASS_KG: TARGET_MASS_KG, &fbb)
    SBM.add(TARGET_L_C_M: TARGET_L_C_M, &fbb)
    SBM.add(IMPACTOR_MASS_KG: IMPACTOR_MASS_KG, &fbb)
    SBM.add(IMPACTOR_L_C_M: IMPACTOR_L_C_M, &fbb)
    SBM.add(RELATIVE_VELOCITY_M_PER_S: RELATIVE_VELOCITY_M_PER_S, &fbb)
    SBM.add(CATASTROPHIC: CATASTROPHIC, &fbb)
    SBM.add(PARENT_POSITION_X_KM: PARENT_POSITION_X_KM, &fbb)
    SBM.add(PARENT_POSITION_Y_KM: PARENT_POSITION_Y_KM, &fbb)
    SBM.add(PARENT_POSITION_Z_KM: PARENT_POSITION_Z_KM, &fbb)
    SBM.add(PARENT_VELOCITY_X_KM_PER_S: PARENT_VELOCITY_X_KM_PER_S, &fbb)
    SBM.add(PARENT_VELOCITY_Y_KM_PER_S: PARENT_VELOCITY_Y_KM_PER_S, &fbb)
    SBM.add(PARENT_VELOCITY_Z_KM_PER_S: PARENT_VELOCITY_Z_KM_PER_S, &fbb)
    SBM.add(MIN_LC_M: MIN_LC_M, &fbb)
    SBM.add(SEED: SEED, &fbb)
    SBM.add(MODEL_NAME: MODEL_NAME, &fbb)
    SBM.add(MODEL_VERSION: MODEL_VERSION, &fbb)
    SBM.add(FRAGMENT_COUNT: FRAGMENT_COUNT, &fbb)
    SBM.add(INPUT_MASS_KG: INPUT_MASS_KG, &fbb)
    SBM.add(OUTPUT_MASS_KG: OUTPUT_MASS_KG, &fbb)
    SBM.addVectorOf(FRAGMENTS: FRAGMENTS, &fbb)
    SBM.addVectorOf(ASSUMPTIONS: ASSUMPTIONS, &fbb)
    SBM.add(COMMENT: COMMENT, &fbb)
    return SBM.endSBM(&fbb, start: __start)
  }

